css_template:
.gallery-card[data-style-element-header="blink_cursor_bar"] {
  border-top: 3px solid var(--card-accent, #ccc);
}
.gallery-card[data-style-element-header="blink_cursor_bar"][data-anim="blink"] {
  animation: header-blink 1s infinite steps(2);
}
@keyframes header-blink {
  0%, 100% { border-top-color: var(--card-accent, #ccc); }
  50% { border-top-color: transparent; }
}

.gallery-card[data-style-element-side="gradient_side_bar"] {
  position: relative;
  padding-left: 12px;
}
.gallery-card[data-style-element-side="gradient_side_bar"]::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 3px;
  background: linear-gradient(to bottom, var(--card-accent, #ccc), transparent);
}

.gallery-card[data-style-element-side="gradient_side_bar_right"] {
        position: relative;
        padding-right: 12px;
    }
    .gallery-card[data-style-element-side="gradient_side_bar_right"]::after {
        content: "";
        position: absolute;
        right: 0; top: 0; bottom: 0;
        width: 3px;
        background: linear-gradient(to bottom, var(--card-accent, #ccc), transparent);
    }

.gallery-card[data-style-element-header="gradient_strip"] {
  border-top: 4px solid transparent;
  border-image: linear-gradient(to right, var(--card-accent, #ccc), var(--card-muted, #999)) 1;
}

.gallery-card[data-style-element-side="line_number_column"] {
  counter-reset: line-no;
  padding-left: 40px;
  position: relative;
}
.gallery-card[data-style-element-side="line_number_column"]::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 36px;
  background: color-mix(in srgb, var(--card-bg, #fff) 90%, var(--card-text, #000) 10%);
  border-right: 1px solid var(--card-muted, #bbb);
}
.gallery-card[data-style-element-side="line_number_column"] .card-highlight-item {
  counter-increment: line-no;
  position: relative;
}
.gallery-card[data-style-element-side="line_number_column"] .card-highlight-item::before {
  content: counter(line-no);
  position: absolute;
  left: -38px;
  width: 28px;
  text-align: right;
  color: var(--card-muted, #999);
  font-size: 0.75em;
  font-family: monospace;
  user-select: none;
}

.gallery-card[data-style-element-side="notebook_binding"] {
  padding-left: 28px;
  position: relative;
}
.gallery-card[data-style-element-side="notebook_binding"]::before {
  content: "○ ○ ○ ○ ○";
  position: absolute;
  left: 2px; top: 0; bottom: 0;
  writing-mode: vertical-rl;
  font-size: 10px;
  letter-spacing: 6px;
  color: var(--card-muted, #bbb);
  pointer-events: none;
}
